import zlib
import base64

EMBEDDED_POOL_B64 = ""
import os
import sys
import ssl
import time
import socket
import random
import math
import statistics
from concurrent.futures import ThreadPoolExecutor

if os.path.exists("real_pool.txt"):
    POOL_FILE = "real_pool.txt"
elif os.path.exists("/kaggle/working/real_pool.txt"):
    POOL_FILE = "/kaggle/working/real_pool.txt"
elif os.path.exists(os.path.join(os.path.dirname(__file__), "real_pool.txt")):
    POOL_FILE = os.path.join(os.path.dirname(__file__), "real_pool.txt")
else:
    POOL_FILE = None

RUN_A_TARGETS = ["speed.cloudflare.com", "www.google.com", "one.one.one.one"]
RUN_B_TARGET = "blnc.traffmonetizer.com"

SSL_CTX = ssl.create_default_context()
SSL_CTX_TRAFF = ssl.create_default_context()
# Note: For traffmonetizer blnc, host certificate is signed by Let's Encrypt / standard CA
# We use standard SSL_CTX to verify full cert chain

TIMEOUT = 8.0
CONCURRENCY = 200

def parse_pool(filepath):
    if filepath and os.path.exists(filepath):
        with open(filepath, "r", encoding="utf-8", errors="ignore") as f:
            lines = [line.strip() for line in f if line.strip()]
    else:
        raw_text = zlib.decompress(base64.b64decode(EMBEDDED_POOL_B64)).decode("utf-8", errors="ignore")
        lines = [line.strip() for line in raw_text.splitlines() if line.strip()]

    total_lines = len(lines)
    
    # Map IP -> list of entries
    # entry: (port, latency, tier, raw_line)
    ip_map = {}
    
    for l in lines:
        parts = l.split("\t")
        ep = parts[0].strip().split()[0]
        if ":" not in ep:
            continue
        ip, port_str = ep.rsplit(":", 1)
        try:
            port = int(port_str)
        except ValueError:
            continue

        # Extract tier tag (FAST / MED / SLOW / UNTAGGED)
        tier = "UNTAGGED"
        for p in parts:
            p_strip = p.strip()
            if p_strip in ("FAST", "MED", "SLOW"):
                tier = p_strip
                break

        # Extract latency if present
        latency = None
        for p in parts:
            p_strip = p.strip()
            if p_strip.isdigit():
                val = int(p_strip)
                if val > 10 and val not in (80, 443, 1080, 3128, 8080, 8888, 999):
                    latency = val
                    break

        if ip not in ip_map:
            ip_map[ip] = []
        ip_map[ip].append({
            "port": port,
            "latency": latency,
            "tier": tier,
            "line": l
        })

    return total_lines, ip_map

def choose_best_port(entries):
    # Lowest latency field if present, else 443, then 3128, else first
    with_lat = [e for e in entries if e["latency"] is not None]
    if with_lat:
        with_lat.sort(key=lambda x: x["latency"])
        return with_lat[0]["port"]

    ports = [e["port"] for e in entries]
    if 443 in ports:
        return 443
    if 3128 in ports:
        return 3128
    return ports[0]

def determine_ip_tier(entries):
    tiers = [e["tier"] for e in entries]
    if "FAST" in tiers:
        return "FAST"
    if "MED" in tiers:
        return "MED"
    if "SLOW" in tiers:
        return "SLOW"
    return "UNTAGGED"

def probe_tls_handshake(sock, target, timeout=TIMEOUT):
    try:
        sock.setblocking(True)
        sock.settimeout(timeout)
        req = f"CONNECT {target}:443 HTTP/1.1\r\nHost: {target}:443\r\n\r\n".encode()
        sock.sendall(req)
        resp = b""
        while b"\r\n\r\n" not in resp:
            chunk = sock.recv(512)
            if not chunk:
                return False
            resp += chunk
            if len(resp) > 2048:
                return False
        first_line = resp.split(b"\r\n")[0]
        if not (b" 200" in first_line or b"HTTP/1.1 200" in first_line or b"HTTP/1.0 200" in first_line):
            return False
        parts = resp.split(b"\r\n\r\n", 1)
        trailing = parts[1] if len(parts) > 1 else b""
        if trailing and trailing[:1] != b"\x16":
            return False
        ss = SSL_CTX.wrap_socket(sock, server_hostname=target)
        ss.settimeout(timeout)
        ss.do_handshake()
        cert = ss.getpeercert()
        ss.close()
        return bool(cert)
    except Exception:
        try:
            sock.close()
        except Exception:
            pass
        return False

def probe_target(ip, port, target, timeout=TIMEOUT):
    s = None
    try:
        s = socket.create_connection((ip, port), timeout=timeout)
        return probe_tls_handshake(s, target, timeout=timeout)
    except Exception:
        if s:
            try:
                s.close()
            except Exception:
                pass
        return False

def run_a_probe(item):
    ip, port = item
    # Primary target probe with connected socket
    s = None
    try:
        s = socket.create_connection((ip, port), timeout=TIMEOUT)
        if probe_tls_handshake(s, RUN_A_TARGETS[0], timeout=TIMEOUT):
            return ip, port, True, RUN_A_TARGETS[0]
    except Exception:
        if s:
            try:
                s.close()
            except Exception:
                pass

    for t in RUN_A_TARGETS[1:]:
        if probe_target(ip, port, t, timeout=TIMEOUT):
            return ip, port, True, t

    return ip, port, False, None

def run_b_probe(item):
    ip, port = item
    s = None
    t0 = time.perf_counter()
    try:
        s = socket.create_connection((ip, port), timeout=TIMEOUT)
        s.setblocking(True)
        s.settimeout(TIMEOUT)
        req = f"CONNECT {RUN_B_TARGET}:443 HTTP/1.1\r\nHost: {RUN_B_TARGET}:443\r\n\r\n".encode()
        s.sendall(req)
        resp = b""
        while b"\r\n\r\n" not in resp:
            chunk = s.recv(512)
            if not chunk:
                return ip, port, False, None
            resp += chunk
            if len(resp) > 2048:
                return ip, port, False, None
        first_line = resp.split(b"\r\n")[0]
        if not (b" 200" in first_line or b"HTTP/1.1 200" in first_line or b"HTTP/1.0 200" in first_line):
            s.close()
            return ip, port, False, None
        parts = resp.split(b"\r\n\r\n", 1)
        trailing = parts[1] if len(parts) > 1 else b""
        if trailing and trailing[:1] != b"\x16":
            s.close()
            return ip, port, False, None
        ss = SSL_CTX_TRAFF.wrap_socket(s, server_hostname=RUN_B_TARGET)
        ss.settimeout(TIMEOUT)
        ss.do_handshake()
        cert = ss.getpeercert()
        ss.close()
        elapsed_ms = (time.perf_counter() - t0) * 1000.0
        if cert:
            return ip, port, True, elapsed_ms
        return ip, port, False, None
    except Exception:
        if s:
            try:
                s.close()
            except Exception:
                pass
        return ip, port, False, None

def main():
    print("=" * 75)
    print("KAGGLE CONTAINER PROBE: REAL_POOL APP-WIRABLE MEASUREMENT")
    print("=" * 75)

    

    total_lines, ip_map = parse_pool(POOL_FILE)
    unique_ips = len(ip_map)
    lines_per_ip = total_lines / unique_ips if unique_ips else 0
    duplicate_inflation = ((total_lines - unique_ips) / unique_ips) * 100 if unique_ips else 0

    print(f"\n1. POOL INFLATION & UNIQUE EXIT IP METRICS:")
    print(f"   - Total lines in pool : {total_lines:,}")
    print(f"   - Unique exit IPs     : {unique_ips:,}")
    print(f"   - Lines per IP        : {lines_per_ip:.3f}")
    print(f"   - Duplicate inflation : {duplicate_inflation:.2f}% (excess ports per IP)")

    # Group by tier
    tier_groups = {"FAST": [], "MED": [], "SLOW": [], "UNTAGGED": []}
    for ip, entries in ip_map.items():
        tier = determine_ip_tier(entries)
        best_port = choose_best_port(entries)
        tier_groups[tier].append((ip, best_port))

    print(f"\n2. UNIQUE EXIT IPs BY TIER GROUP:")
    for tier in ["FAST", "MED", "SLOW", "UNTAGGED"]:
        count = len(tier_groups[tier])
        pct = (count / unique_ips) * 100
        print(f"   - {tier:<9}: {count:>6,} IPs ({pct:6.2f}%)")

    # Proportional sampling of 1,500 unique IPs
    TARGET_SAMPLE = min(1500, unique_ips)
    sampled_by_tier = {}
    allocated = 0
    tiers_ordered = ["FAST", "MED", "SLOW", "UNTAGGED"]

    for tier in tiers_ordered:
        k = int(round(TARGET_SAMPLE * (len(tier_groups[tier]) / unique_ips)))
        k = min(k, len(tier_groups[tier]))
        sampled_by_tier[tier] = k
        allocated += k

    diff = TARGET_SAMPLE - allocated
    if diff != 0:
        # adjust largest group
        largest = max(tiers_ordered, key=lambda t: len(tier_groups[t]))
        sampled_by_tier[largest] += diff

    sample_items = []
    sample_items_by_tier = {}
    random.seed(42)  # reproducible random seed
    for tier in tiers_ordered:
        k = sampled_by_tier[tier]
        chosen = random.sample(tier_groups[tier], k) if k > 0 else []
        sample_items_by_tier[tier] = chosen
        sample_items.extend([(ip, p, tier) for ip, p in chosen])

    print(f"\n3. PROPORTIONAL SAMPLING (Total: {len(sample_items)} IPs):")
    for tier in tiers_ordered:
        print(f"   - {tier:<9}: sampled {len(sample_items_by_tier[tier])} IPs")

    # Run A: General Targets
    print(f"\n4. EXECUTING RUN A: General Targets ({', '.join(RUN_A_TARGETS)})")
    print(f"   Concurrency: {CONCURRENCY}, Timeout: {TIMEOUT}s ...")
    t_start_a = time.time()
    
    run_a_results = {}
    with ThreadPoolExecutor(max_workers=CONCURRENCY) as ex:
        futures = {ex.submit(run_a_probe, (ip, port)): (ip, port, tier) for ip, port, tier in sample_items}
        for fut in futures:
            ip, port, tier = futures[fut]
            _, _, ok, target = fut.result()
            run_a_results[ip] = (ok, target)

    print(f"   Run A completed in {time.time() - t_start_a:.1f}s")

    # Run B: TraffMonetizer Target
    print(f"\n5. EXECUTING RUN B: TraffMonetizer Only ({RUN_B_TARGET}:443)")
    print(f"   Concurrency: {CONCURRENCY}, Timeout: {TIMEOUT}s ...")
    t_start_b = time.time()

    run_b_results = {}
    with ThreadPoolExecutor(max_workers=CONCURRENCY) as ex:
        futures = {ex.submit(run_b_probe, (ip, port)): (ip, port, tier) for ip, port, tier in sample_items}
        for fut in futures:
            ip, port, tier = futures[fut]
            _, _, ok, ms = fut.result()
            run_b_results[ip] = (ok, ms)

    print(f"   Run B completed in {time.time() - t_start_b:.1f}s")

    # Tier Breakdown Analysis
    print("\n" + "=" * 85)
    print(f"{'Tier':<10} | {'Sampled':<8} | {'Run A Pass %':<15} | {'Run B Pass %':<15} | {'Run B Median ms':<16}")
    print("-" * 85)

    tier_stats = {}
    all_a_pass = 0
    all_b_pass = 0
    all_b_ms = []

    for tier in tiers_ordered:
        items = sample_items_by_tier[tier]
        n_tier = len(items)
        if n_tier == 0:
            print(f"{tier:<10} | {0:<8} | {'N/A':<15} | {'N/A':<15} | {'N/A':<16}")
            continue

        a_pass = sum(1 for ip, _ in items if run_a_results[ip][0])
        b_pass = sum(1 for ip, _ in items if run_b_results[ip][0])
        b_ms_list = [run_b_results[ip][1] for ip, _ in items if run_b_results[ip][0] and run_b_results[ip][1] is not None]

        all_a_pass += a_pass
        all_b_pass += b_pass
        all_b_ms.extend(b_ms_list)

        pct_a = (a_pass / n_tier) * 100
        pct_b = (b_pass / n_tier) * 100
        med_b_ms = statistics.median(b_ms_list) if b_ms_list else 0.0

        tier_stats[tier] = {
            "n": n_tier,
            "a_pass": a_pass,
            "b_pass": b_pass,
            "pct_a": pct_a,
            "pct_b": pct_b,
            "med_b_ms": med_b_ms
        }
        med_str = f"{med_b_ms:8.1f} ms" if b_ms_list else "N/A"
        print(f"{tier:<10} | {n_tier:<8} | {pct_a:6.2f}% ({a_pass:>4})   | {pct_b:6.2f}% ({b_pass:>4})   | {med_str:<16}")

    print("-" * 85)
    total_sampled = len(sample_items)
    overall_pct_a = (all_a_pass / total_sampled) * 100
    overall_pct_b = (all_b_pass / total_sampled) * 100
    overall_med_b_ms = statistics.median(all_b_ms) if all_b_ms else 0.0
    print(f"{'OVERALL':<10} | {total_sampled:<8} | {overall_pct_a:6.2f}% ({all_a_pass:>4})   | {overall_pct_b:6.2f}% ({all_b_pass:>4})   | {overall_med_b_ms:8.1f} ms")
    print("=" * 85)

    # 95% Confidence Interval for Run A and Run B
    fpc = math.sqrt((unique_ips - total_sampled) / (unique_ips - 1)) if unique_ips > 1 else 1.0
    z = 1.95996

    p_a = all_a_pass / total_sampled
    se_a = math.sqrt((p_a * (1 - p_a)) / total_sampled) * fpc
    ci_a_low = max(0.0, p_a - z * se_a)
    ci_a_high = min(1.0, p_a + z * se_a)
    scaled_a_est = int(round(unique_ips * p_a))
    scaled_a_low = int(round(unique_ips * ci_a_low))
    scaled_a_high = int(round(unique_ips * ci_a_high))

    p_b = all_b_pass / total_sampled
    se_b = math.sqrt((p_b * (1 - p_b)) / total_sampled) * fpc
    ci_b_low = max(0.0, p_b - z * se_b)
    ci_b_high = min(1.0, p_b + z * se_b)
    scaled_b_est = int(round(unique_ips * p_b))
    scaled_b_low = int(round(unique_ips * ci_b_low))
    scaled_b_high = int(round(unique_ips * ci_b_high))

    print(f"\n6. SCALED UNIQUE EXIT IP ESTIMATES (95% CI with Finite Population Correction):")
    print(f"   - Run A (General DePIN / Web):")
    print(f"       Pass Proportion : {overall_pct_a:.2f}% (±{z * se_a * 100:.2f}%)")
    print(f"       Scaled Unique IPs: {scaled_a_est:,} [95% CI: {scaled_a_low:,} – {scaled_a_high:,}]")
    print(f"   - Run B (TraffMonetizer Backend):")
    print(f"       Pass Proportion : {overall_pct_b:.2f}% (±{z * se_b * 100:.2f}%)")
    print(f"       Scaled Unique IPs: {scaled_b_est:,} [95% CI: {scaled_b_low:,} – {scaled_b_high:,}]")

    # Arithmetic Analysis
    print(f"\n7. CAPACITY & SUPPLY ARITHMETIC (Measured Run B Rate = {overall_pct_b:.2f}%, Death Rate = 23.0% / pass):")
    print("=" * 85)
    print(f"{'Target Nodes':<14} | {'Unique IPs Needed':<20} | {'Replacements/hr':<18} | {'Raw Supply Needed/hr':<22}")
    print("-" * 85)
    
    target_nodes_list = [1688, 3597, 15000]
    for target in target_nodes_list:
        needed_ips = int(round(target / p_b)) if p_b > 0 else 0
        hourly_deaths = int(round(target * 0.23))
        raw_supply_needed = int(round(hourly_deaths / p_b)) if p_b > 0 else 0
        print(f"{target:<14,d} | {needed_ips:<20,d} | {hourly_deaths:<18,d} | {raw_supply_needed:<22,d}")

    print("=" * 85)

if __name__ == "__main__":
    main()
